#include "all_your_base.h"
#include <cassert>
#include <cstdint>
#include <iostream>
#include <stdexcept>
#include <vector>

using namespace all_your_base;

static void should_throw(unsigned int in_base, std::vector<unsigned int> digits, unsigned int out_base) {
    bool caught = false;
    try { (void)convert(in_base, digits, out_base); }
    catch (const std::invalid_argument&) { caught = true; }
    assert(caught && "expected invalid_argument");
}

int main() {
    assert((convert(2, {1}, 10) == std::vector<unsigned int>{1}));
    assert((convert(2, {1,0,1}, 10) == std::vector<unsigned int>{5}));
    assert((convert(10, {5}, 2) == std::vector<unsigned int>{1,0,1}));
    assert((convert(2, {1,0,1,0,1,0}, 10) == std::vector<unsigned int>{4,2}));
    assert((convert(10, {4,2}, 2) == std::vector<unsigned int>{1,0,1,0,1,0}));
    assert((convert(3, {1,1,2,0}, 16) == std::vector<unsigned int>{2,10}));
    assert((convert(16, {2,10}, 3) == std::vector<unsigned int>{1,1,2,0}));
    assert((convert(97, {3,46,60}, 73) == std::vector<unsigned int>{6,10,45}));
    assert((convert(2, {}, 10) == std::vector<unsigned int>{}));
    assert((convert(10, {0}, 2) == std::vector<unsigned int>{}));
    assert((convert(10, {0,0,0}, 2) == std::vector<unsigned int>{}));
    assert((convert(7, {0,6,0}, 10) == std::vector<unsigned int>{4,2}));
    should_throw(1, {}, 10);
    should_throw(0, {}, 10);
    should_throw(2, {1,2,1,0,1,0}, 10);
    should_throw(2, {1,0,1,0,1,0}, 1);
    should_throw(10, {7}, 0);

    // Value 32749 in both directions
    assert((convert(97, {3,46,60}, 10) == std::vector<unsigned int>{3,2,7,4,9}));
    assert((convert(10, {3,2,7,4,9}, 73) == std::vector<unsigned int>{6,10,45}));

    // Exceeds 64 bits: (2^32-2) repeated twice in base 2^32-1, to base 7.
    // Exact output is checked by decoding back to decimal digits.
    const unsigned int big_base = 0xFFFFFFFFU - 1 == 0 ? 0u : 4294967294U;
    auto out = convert(big_base, {big_base - 1, big_base - 1}, 7);
    auto back = convert(7, out, big_base);
    assert((back == std::vector<unsigned int>{big_base - 1, big_base - 1}));
    std::cout << "huge base digits: " << out.size() << '\n';

    // Same input to base 2 and decode value with __int128 oracle.
    auto bits = convert(big_base, {big_base - 1, big_base - 1}, 2);
    unsigned __int128 value = 0;
    for (unsigned int b : bits) value = value * 2 + b;
    unsigned __int128 expected = (unsigned __int128)(big_base - 1) * big_base + (big_base - 1);
    assert(value == expected);

    // Huge intermediate with many binary digits to a large output base.
    std::vector<unsigned int> many_ones(300, 1);
    auto large = convert(2, many_ones, 1000000000U);
    assert(!large.empty());
    assert(large.front() <= 999999999U);
    auto back2 = convert(1000000000U, large, 2);
    assert(back2 == many_ones);

    std::cout << "all edge checks passed\n";
    return 0;
}
